// Light by day as in the prototype, and a dimmer navy at night so the face never outshines the screen.
const PAPER = { light: '#FFFFFF', dark: '#1d3561' };
const INK = { light: '#121A2E', dark: '#eef4ff' };
const FAINT = { light: '#121A2E8C', dark: '#eef4ff8C' };
const RING = { light: '#121A2E', dark: '#FFFFFF80' };
const CROSSED = { light: '#121A2E66', dark: '#eef4ff8F' };
const CROSSED_RING = { light: '#121A2E66', dark: '#FFFFFF47' };
const CART = 'M3 4h2.5l2.2 11h10.6L20.5 7H7 M8.1 19.5A1.4 1.4 0 1 0 10.9 19.5A1.4 1.4 0 1 0 8.1 19.5Z '
  + 'M15.6 19.5A1.4 1.4 0 1 0 18.4 19.5A1.4 1.4 0 1 0 15.6 19.5Z';

// Open items first, oldest first, then the crossed ones that still fit, newest first; then back in the order
// they were added, so a crossed item stays where it was until open ones need its place.
function shown(d, slots) {
  const open = d.open.slice(0, slots);
  const rows = open.concat(d.crossed.slice(0, slots - open.length));
  return rows.sort((a, b) => b.minutesAgo - a.minutesAgo);
}

function item(row, u) {
  return { type: 'button', action: 'toggle', rowId: row.id, children: [
    { type: 'hstack', spacing: 8 * u, frame: { maxWidth: 'infinity', alignment: 'leading' }, children: [
      { type: 'circle', frame: { width: 17 * u, height: 17 * u },
        fill: row.done ? CROSSED_RING : null, stroke: row.done ? null : { color: RING, width: 1.6 * u } },
      { type: 'text', value: row.title || 'Something', size: 14 * u, weight: 'semibold',
        color: row.done ? CROSSED : INK, strikethrough: row.done, lineLimit: 1 },
    ] } ] };
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall.
  const u = ctx.height / 170;
  const d = ctx.data;
  const wide = ctx.family === 'medium';
  const rows = shown(d, wide ? 6 : 4);
  const pairs = [];
  for (let i = 0; i < rows.length; i += 2) pairs.push(rows.slice(i, i + 2));

  return {
    type: 'vstack', align: 'leading', spacing: 0,
    padding: { top: 15 * u, leading: 16 * u, trailing: 10 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
    widgetBackground: PAPER,
    children: [
      { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
        { type: 'path', d: CART, viewBox: [0, 0, 24, 24], frame: { width: 15 * u, height: 15 * u },
          stroke: { color: INK, width: 2.4 * 15 * u / 24, cap: 'round' } },
        { type: 'text', value: 'Groceries', size: 13 * u, weight: 'bold', color: INK, lineLimit: 1, minScale: 0.8 },
        { type: 'spacer', minLength: 0 },
        wide && d.left > 0 && { type: 'text', value: d.left + ' left', size: 13 * u, weight: 'semibold', color: FAINT,
          lineLimit: 1 },
        { type: 'button', action: 'add', children: [
          { type: 'symbol', name: 'plus', size: 13 * u, weight: 'bold', color: FAINT,
            frame: { width: 30, height: 30 } } ] },
      ] },
      rows.length === 0 && { type: 'text', value: 'Nothing on the list. Tap + to add the first thing.',
        size: 14 * u, weight: 'semibold', color: FAINT, lineLimit: 2, padding: { top: 14 * u, trailing: 6 * u } },
      { type: 'vstack', align: 'leading', spacing: 9 * u, padding: { top: 12.5 * u, trailing: 6 * u },
        children: wide
          ? pairs.map((pair) => ({ type: 'hstack', spacing: 12 * u, children: [
            item(pair[0], u), pair[1] ? item(pair[1], u) : { type: 'spacer' }] }))
          : rows.map((row) => item(row, u)) },
    ],
  };
}
